from typing import List
from bisect import bisect_right

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        indexed = [(l, r, w, i) for i, (l, r, w) in enumerate(intervals)]
        indexed.sort(key=lambda x: x[0])

        n = len(indexed)
        starts = [x[0] for x in indexed]

        dp = [[(0, []) for _ in range(5)] for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            l, r, w, idx = indexed[i]
            nxt = bisect_right(starts, r)

            for k in range(1, 5):
                best_skip = dp[i + 1][k]

                next_weight, next_indices = dp[nxt][k - 1]
                take_indices = sorted(next_indices + [idx])
                best_take = (w + next_weight, take_indices)

                if best_take[0] > best_skip[0]:
                    dp[i][k] = best_take
                elif best_take[0] < best_skip[0]:
                    dp[i][k] = best_skip
                else:
                    dp[i][k] = best_take if best_take[1] < best_skip[1] else best_skip

        return dp[0][4][1]
